351	func publicViolations(violations []Violation) []Validation {
352		public := make([]Validation, 0, len(violations))
353		for _, violation := range violations {
354			public = append(public, Validation{
355				Code:    violation.Code,
356				TraceID: violation.TraceID,
357				SpanID:  violation.SpanID,
358				Message: violation.Message,
359			})
360		}
361		return public
362	}
