364	// GetTrace reassembles one trace and fails when it is incomplete or unusable.
365	func (s *Service) GetTrace(traceID string) (any, error) {
366		value, err := s.store.View(func(state *State) (any, error) {
367			spans, found := state.Spans[traceID]
368			if !found {
369				return nil, NotFoundError("trace %s does not exist", traceID)
370			}
371			return assembleTrace(traceID, spans), nil
372		})
373		if err != nil {
374			return nil, err
375		}
376		trace := value.(*Trace)
377		if !trace.Complete {
378			return nil, InvalidTraceError(traceID, append([]Violation{{
379				Code:    "trace_incomplete",
380				TraceID: traceID,
381				SpanID:  "",
382				Message: "trace is not complete yet or its declared span_count does not match the ingested spans",
383			}}, trace.Violations...))
384		}
385		if !trace.Valid {
386			return nil, InvalidTraceError(traceID, trace.Violations)
387		}
388		return trace, nil
389	}
