391	// TraceFilter narrows GET /traces. Every condition that is set must hold; a
392	// zero-valued filter keeps every trace. Time and duration fields are present as
393	// pointers so that an unset bound never accidentally matches as zero.
394	type TraceFilter struct {
395		// Query is matched as a Unicode case-insensitive substring of the trace id
396		// or of any span service or operation.
397		Query string
398		// Operation keeps traces that have at least one span with this exact op.
399		Operation string
400		// Service keeps traces that contain this service (the legacy semantics).
401		Service string
402		// Status is "", "error" (at least one error span) or "ok" (no error span).
403		Status string
404		// StartFrom is inclusive and StartTo is exclusive on the root start time.
405		StartFrom *time.Time
406		StartTo   *time.Time
407		// MinDurationNS and MaxDurationNS are both inclusive on the root duration.
408		MinDurationNS *int64
409		MaxDurationNS *int64
410		// Complete and Valid filter on the current reassembly result; nil = unset.
411		Complete *bool
412		Valid    *bool
413		// ServicePath is an ordered chain of two or more service names. A trace
414		// matches when it holds spans s1..sn, each a direct child of the previous
415		// one, whose services equal the chain element by element. Nil means unset.
416		ServicePath []string
417	}
418	
419	// TraceFilterFromQuery parses and validates every documented GET /traces
420	// parameter apart from limit, which the HTTP layer keeps. Unknown parameters
421	// are rejected before this is called. All failures are validation errors.
422	func TraceFilterFromQuery(query url.Values) (*TraceFilter, error) {
423		filter := &TraceFilter{
424			Query:   query.Get("q"),
425			Service: strings.TrimSpace(query.Get("service")),
426		}
427		if raw, present := query.Get("operation"), query.Has("operation"); present {
428			operation := strings.TrimSpace(raw)
429			if operation == "" {
430				return nil, ValidationError("operation must not be empty")
431			}
432			filter.Operation = operation
433		}
434		if query.Has("status") {
435			status := query.Get("status")
436			if status != "ok" && status != "error" {
437				return nil, ValidationError("status must be ok or error")
438			}
439			filter.Status = status
440		}
441		if raw, present := query.Get("start_from"), query.Has("start_from"); present {
442			instant, err := parseTime(raw, "start_from")
443			if err != nil {
444				return nil, err
445			}
446			filter.StartFrom = &instant
447		}
448		if raw, present := query.Get("start_to"), query.Has("start_to"); present {
449			instant, err := parseTime(raw, "start_to")
450			if err != nil {
451				return nil, err
452			}
453			filter.StartTo = &instant
454		}
455		if raw, present := query.Get("min_duration_ns"), query.Has("min_duration_ns"); present {
456			value, err := parseDurationBound(raw, "min_duration_ns")
457			if err != nil {
458				return nil, err
459			}
460			filter.MinDurationNS = &value
461		}
462		if raw, present := query.Get("max_duration_ns"), query.Has("max_duration_ns"); present {
463			value, err := parseDurationBound(raw, "max_duration_ns")
464			if err != nil {
465				return nil, err
466			}
467			filter.MaxDurationNS = &value
468		}
469		if filter.MinDurationNS != nil && filter.MaxDurationNS != nil &&
470			*filter.MinDurationNS > *filter.MaxDurationNS {
471			return nil, ValidationError("min_duration_ns must not be greater than max_duration_ns")
472		}
473		if raw, present := query.Get("complete"), query.Has("complete"); present {
474			value, err := parseBoolean(raw, "complete")
475			if err != nil {
476				return nil, err
477			}
478			filter.Complete = &value
479		}
480		if raw, present := query.Get("valid"), query.Has("valid"); present {
481			value, err := parseBoolean(raw, "valid")
482			if err != nil {
483				return nil, err
484			}
485			filter.Valid = &value
486		}
487		if query.Has("service_path") {
488			path, err := parseServicePath(query["service_path"])
489			if err != nil {
490				return nil, err
491			}
492			filter.ServicePath = path
493		}
494		return filter, nil
495	}
496	
497	const (
498		// maxServicePathItems bounds the number of service_path elements and
499		// maxServicePathName the length of each name.
500		maxServicePathItems = 32
501		maxServicePathName  = 128
502	)
503	
504	// parseServicePath validates the repeated service_path parameter. Names are
505	// kept verbatim because matching is exact, so no whitespace is trimmed.
506	func parseServicePath(names []string) ([]string, error) {
507		if len(names) < 2 || len(names) > maxServicePathItems {
508			return nil, ValidationError("service_path must contain between 2 and %d service names", maxServicePathItems)
509		}
510		for index, name := range names {
511			if name == "" {
512				return nil, ValidationError("service_path names must not be empty")
513			}
514			if len(name) > maxServicePathName {
515				return nil, ValidationError("service_path names must be at most %d characters", maxServicePathName)
516			}
517			if index > 0 && names[index-1] == name {
518				return nil, ValidationError("service_path names must differ from their neighbour")
519			}
520		}
521		return names, nil
522	}
523	
524	// parseDurationBound accepts a decimal non-negative integer with no sign,
525	// exponent or surrounding space.
526	func parseDurationBound(raw string, field string) (int64, error) {
527		if raw == "" || strings.TrimSpace(raw) == "" {
528			return 0, ValidationError("%s must be a decimal non-negative integer", field)
529		}
530		for _, r := range raw {
531			if r < '0' || r > '9' {
532				return 0, ValidationError("%s must be a decimal non-negative integer", field)
533			}
534		}
535		value, err := strconv.ParseInt(raw, 10, 64)
536		if err != nil {
537			return 0, ValidationError("%s must be a decimal non-negative integer", field)
538		}
539		return value, nil
540	}
541	
542	// parseBoolean accepts exactly "true" or "false".
543	func parseBoolean(raw string, field string) (bool, error) {
544		switch raw {
545		case "true":
546			return true, nil
547		case "false":
548			return false, nil
549		default:
550			return false, ValidationError("%s must be true or false", field)
551		}
552	}
553	
554	// matches reports whether one reassembled trace satisfies every set condition.
555	func (f *TraceFilter) matches(trace *Trace) bool {
556		if f.Service != "" {
557			found := false
558			for _, node := range trace.Spans {
559				if node.Service == f.Service {
560					found = true
561					break
562				}
563			}
564			if !found {
565				return false
566			}
567		}
568		if f.Operation != "" {
569			found := false
570			for _, node := range trace.Spans {
571				if node.Operation == f.Operation {
572					found = true
573					break
574				}
575			}
576			if !found {
577				return false
578			}
579		}
580		if f.Query != "" {
581			if !containsFold(trace.TraceID, f.Query) {
582				found := false
583				for _, node := range trace.Spans {
584					if containsFold(node.Service, f.Query) || containsFold(node.Operation, f.Query) {
585						found = true
586						break
587					}
588				}
589				if !found {
590					return false
591				}
592			}
593		}
594		switch f.Status {
595		case "error":
596			if trace.ErrorSpans == 0 {
597				return false
598			}
599		case "ok":
600			if trace.ErrorSpans != 0 {
601				return false
602			}
603		}
604		if f.Complete != nil && trace.Complete != *f.Complete {
605			return false
606		}
607		if f.Valid != nil && trace.Valid != *f.Valid {
608			return false
609		}
610		if len(f.ServicePath) > 0 && !matchServicePath(trace.Spans, f.ServicePath) {
611			return false
612		}
613		if f.StartFrom != nil || f.StartTo != nil || f.MinDurationNS != nil || f.MaxDurationNS != nil {
614			// Every time and duration bound refers to the root. A trace without a
615			// root has neither a root instant nor a root duration, so any such
616			// bound excludes it.
617			if trace.Root == nil {
618				return false
619			}
620		}
621		if f.StartFrom != nil || f.StartTo != nil {
622			rootStart, err := parseTime(trace.Root.StartTime, "start_time")
623			if err != nil {
624				return false
625			}
626			if f.StartFrom != nil && rootStart.Before(*f.StartFrom) {
627				return false
628			}
629			if f.StartTo != nil && !rootStart.Before(*f.StartTo) {
630				return false
631			}
632		}
633		if f.MinDurationNS != nil && trace.DurationNS < *f.MinDurationNS {
634			return false
635		}
636		if f.MaxDurationNS != nil && trace.DurationNS > *f.MaxDurationNS {
637			return false
638		}
639		return true
640	}
641	
642	// matchServicePath reports whether the reassembled span tree contains a chain
643	// of direct parent/child spans whose services equal path element by element.
644	// The chain may start at any span; only the stored parent/child links are
645	// consulted, so an incomplete or invalid trace is judged on the spans it has.
646	func matchServicePath(nodes []*TraceNode, path []string) bool {
647		for _, node := range nodes {
648			if matchServicePathFrom(node, path, 0) {
649				return true
650			}
651		}
652		return false
653	}
654	
655	func matchServicePathFrom(node *TraceNode, path []string, index int) bool {
656		if node.Service != path[index] {
657			return false
658		}
659		if index == len(path)-1 {
660			return true
661		}
662		for _, child := range node.Children {
663			if matchServicePathFrom(child, path, index+1) {
664				return true
665			}
666		}
667		return false
668	}
669	
670	// ListTraces summarises every stored trace with at least one span.
671	func (s *Service) ListTraces(filter *TraceFilter, limit int) (any, error) {
672		if limit < 1 || limit > 400 {
673			return nil, ValidationError("limit must be between 1 and 400")
674		}
675		if filter == nil {
676			filter = &TraceFilter{}
677		}
678		value, err := s.store.View(func(state *State) (any, error) {
679			summaries := []*TraceSummary{}
680			for _, traceID := range state.traceIDs() {
681				trace := assembleTrace(traceID, state.Spans[traceID])
682				if !filter.matches(trace) {
683					continue
684				}
685				summary := &TraceSummary{
686					TraceID:      trace.TraceID,
687					StartTime:    "",
688					DurationNS:   trace.DurationNS,
689					SpanCount:    trace.SpanCount,
690					ServiceCount: trace.ServiceCount,
691					ErrorSpans:   trace.ErrorSpans,
692					Complete:     trace.Complete,
693					Valid:        trace.Valid,
694				}
695				if trace.Root != nil {
696					rootID := trace.Root.SpanID
697					rootService := trace.Root.Service
698					summary.RootSpanID = &rootID
699					summary.RootService = &rootService
700					summary.StartTime = trace.Root.StartTime
701					summary.rootInstant, _ = parseTime(trace.Root.StartTime, "start_time")
702				}
703				summaries = append(summaries, summary)
704			}
705			sort.Slice(summaries, func(i, j int) bool {
706				if !summaries[i].rootInstant.Equal(summaries[j].rootInstant) {
707					return summaries[i].rootInstant.After(summaries[j].rootInstant)
708				}
709				return summaries[i].TraceID < summaries[j].TraceID
710			})
711			if len(summaries) > limit {
712				summaries = summaries[:limit]
713			}
714			return map[string]any{"traces": summaries}, nil
715		})
716		if err != nil {
717			return nil, err
718		}
719		return value, nil
720	}
721	
722	// CriticalPath walks the root-to-leaf path with the largest total self_time. It
723	// therefore needs time containment to hold, exactly like the invariant
724	// "critical path length equals the root span duration" does.
725	func (s *Service) CriticalPath(traceID string) (any, error) {
726		value, err := s.store.View(func(state *State) (any, error) {
727			spans, found := state.Spans[traceID]
728			if !found {
729				return nil, NotFoundError("trace %s does not exist", traceID)
730			}
731			return assembleTrace(traceID, spans), nil
732		})
733		if err != nil {
734			return nil, err
735		}
736		trace := value.(*Trace)
737		path := &CriticalPath{
738			TraceID:         traceID,
739			Method:          "longest chain below the root, weighted by self_time_ns; ties are broken by the longest sub-chain and then by the smallest span id sequence",
740			TraceDurationNS: trace.DurationNS,
741			Path:            []PathStep{},
742			Complete:        trace.Complete,
743			Valid:           trace.Valid || trace.Root == nil,
744			Violations:      publicViolations(trace.Violations),
745		}
746		if !trace.Complete {
747			path.Valid = false
748		}
749		if trace.Root == nil {
750			return path, nil
751		}
752		_, steps := longestSelfTimePath(trace.Root)
753		path.Path = steps
754		for _, step := range steps {
755			path.LengthNS += step.SelfTimeNS
756		}
757		return path, nil
758	}
759	
760	type pathCandidate struct {
761		// weight is the sum of self_time along the candidate: the value the response
762		// reports as the length of the path.
763		weight int64
764		// path is the longest self_time-weighted path of the subtree, used to break a
765		// tie between two branches that weigh the same.
766		path  int64
767		steps int
768		ids   []string
769	}
770	
771	// better ranks two candidates of the same node. More self_time wins. An equal
772	// weight is settled by the branch with the longer critical path, then by the
773	// shorter path, then by the lexicographically smallest span id sequence, so the
774	// output is deterministic.
775	func better(candidate pathCandidate, incumbent pathCandidate) bool {
776		if candidate.weight != incumbent.weight {
777			return candidate.weight > incumbent.weight
778		}
779		if candidate.path != incumbent.path {
780			return candidate.path > incumbent.path
781		}
782		if candidate.steps != incumbent.steps {
783			return candidate.steps < incumbent.steps
784		}
785		for index := 0; index < len(candidate.ids) && index < len(incumbent.ids); index++ {
786			if candidate.ids[index] != incumbent.ids[index] {
787				return candidate.ids[index] < incumbent.ids[index]
788			}
789		}
790		return len(candidate.ids) < len(incumbent.ids)
791	}
792	
793	// longestSelfTimePath returns the winning candidate of the subtree together
794	// with the steps of the critical path, both in pre-order. The tree builder has
795	// already computed maxPath for every span, so the winner is the child whose
796	// maxPath is the largest and the weight of the result is this node's maxPath.
797	func longestSelfTimePath(node *TraceNode) (pathCandidate, []PathStep) {
798		self := PathStep{
799			SpanID:     node.SpanID,
800			ParentID:   node.ParentID,
801			Service:    node.Service,
802			Operation:  node.Operation,
803			Depth:      node.Depth,
804			SelfTimeNS: node.SelfTimeNS,
805			StartTime:  node.StartTime,
806			EndTime:    node.EndTime,
807		}
808		best := pathCandidate{weight: node.SelfTimeNS, path: node.maxPath, steps: 1, ids: []string{node.SpanID}}
809		var bestSteps []PathStep
810		for _, child := range node.Children {
811			candidate, steps := longestSelfTimePath(child)
812			candidate.weight += node.SelfTimeNS
813			candidate.steps++
814			candidate.ids = append([]string{node.SpanID}, candidate.ids...)
815			if bestSteps == nil || better(candidate, best) {
816				best = candidate
817				bestSteps = steps
818			}
819		}
820		if bestSteps == nil {
821			bestSteps = []PathStep{}
822		}
823		steps := append([]PathStep{self}, bestSteps...)
824		weight := int64(0)
825		for _, item := range steps {
826			weight += item.SelfTimeNS
827		}
828		best.weight = weight
829		if best.weight < node.maxPath {
830			best.weight = node.maxPath
831		}
832		return best, steps
833	}
834	
835	// ServiceGraph aggregates the caller/callee graph. traceID limits the analysis
836	// to one trace; an empty traceID covers every stored trace.
837	func (s *Service) ServiceGraph(traceID string) (any, error) {
838		value, err := s.store.View(func(state *State) (any, error) {
839			graph := &ServiceGraph{
840				Services: []*ServiceStat{},
841				Edges:    []*ServiceEdge{},
842				Stats:    &GraphStats{},
843			}
844			ids := state.traceIDs()
845			if traceID != "" {
846				if _, found := state.Spans[traceID]; !found {
847					return nil, NotFoundError("trace %s does not exist", traceID)
848				}
849				ids = []string{traceID}
850				// The response always echoes an explicitly requested trace.
851				graph.TraceID = &ids[0]
852			}
853			services := map[string]*ServiceStat{}
854			edges := map[string]*ServiceEdge{}
855			graph.Stats.durations = []int64{}
856			for _, id := range ids {
857				trace := assembleTrace(id, state.Spans[id])
858				usable := trace.Valid && trace.Complete && trace.Root != nil
859				if !usable {
860					if traceID != "" {
861						// An explicitly requested trace is reported as-is, complete
862						// or not.
863						graph.Stats.PartialTraces = 1
864						return graph, nil
865					}
866					graph.Stats.PartialTraces++
867					continue
868				}
869				graph.Stats.TraceCount++
870				graph.Stats.SpanCount += trace.SpanCount
871				graph.Stats.ErrorSpans += trace.ErrorSpans
872				graph.Stats.durations = append(graph.Stats.durations, trace.DurationNS)
873				for _, node := range trace.Spans {
874					stat := services[node.Service]
875					if stat == nil {
876						stat = &ServiceStat{Service: node.Service, Operations: []*OperationStat{}, durations: []int64{}}
877						services[node.Service] = stat
878					}
879					stat.SpanCount++
880					stat.SelfTimeNS += node.SelfTimeNS
881					stat.durations = append(stat.durations, node.DurationNS)
882					if node.Error {
883						stat.ErrorSpans++
884					}
885					if node.ParentID == nil {
886						stat.RootSpans++
887					}
888					operation := operationStat(stat, node.Operation)
889					operation.SpanCount++
890					operation.SelfTimeNS += node.SelfTimeNS
891					operation.durations = append(operation.durations, node.DurationNS)
892					if node.Error {
893						operation.ErrorSpans++
894					}
895				}
896				byID := map[string]*TraceNode{}
897				for _, node := range trace.Spans {
898					byID[node.SpanID] = node
899				}
900				for _, node := range trace.Spans {
901					if node.ParentID == nil {
902						continue
903					}
904					parent := byID[*node.ParentID]
905					if parent == nil || parent.Service == node.Service {
906						continue
907					}
908					key := parent.Service + "\x00" + node.Service
909					edge := edges[key]
910					if edge == nil {
911						edge = &ServiceEdge{Caller: parent.Service, Callee: node.Service, durations: []int64{}}
912						edges[key] = edge
913					}
914					edge.CallCount++
915					edge.durations = append(edge.durations, node.DurationNS)
916					if node.Error {
917						edge.ErrorCount++
918					}
919				}
920			}
921			for _, stat := range services {
922				finalizeService(stat)
923				graph.Services = append(graph.Services, stat)
924			}
925			for _, edge := range edges {
926				finalizeEdge(edge)
927				graph.Edges = append(graph.Edges, edge)
928			}
929			sort.Slice(graph.Services, func(i, j int) bool { return graph.Services[i].Service < graph.Services[j].Service })
930			sort.Slice(graph.Edges, func(i, j int) bool {
931				if graph.Edges[i].Caller != graph.Edges[j].Caller {
932					return graph.Edges[i].Caller < graph.Edges[j].Caller
933				}
934				return graph.Edges[i].Callee < graph.Edges[j].Callee
935			})
936			finalizeStats(graph.Stats)
937			return graph, nil
938		})
939		if err != nil {
940			return nil, err
941		}
942		return value, nil
943	}
944	
945	func operationStat(service *ServiceStat, operation string) *OperationStat {
946		for _, stat := range service.Operations {
947			if stat.Operation == operation {
948				return stat
949			}
950		}
951		stat := &OperationStat{Operation: operation, durations: []int64{}}
952		service.Operations = append(service.Operations, stat)
953		return stat
954	}
955	
956	func finalizeService(stat *ServiceStat) {
957		sort.Slice(stat.durations, func(i, j int) bool { return stat.durations[i] < stat.durations[j] })
958		stat.MinDurationNS, stat.MaxDurationNS = bounds(stat.durations)
959		stat.MeanDurationNS = mean(stat.durations)
960		stat.P50DurationNS = percentile(stat.durations, 50)
961		stat.P95DurationNS = percentile(stat.durations, 95)
962		stat.durations = nil
963		sort.Slice(stat.Operations, func(i, j int) bool { return stat.Operations[i].Operation < stat.Operations[j].Operation })
964		for _, operation := range stat.Operations {
965			finalizeOperation(operation)
966		}
967	}
968	
969	func finalizeOperation(stat *OperationStat) {
970		sort.Slice(stat.durations, func(i, j int) bool { return stat.durations[i] < stat.durations[j] })
971		stat.MinDurationNS, stat.MaxDurationNS = bounds(stat.durations)
972		stat.MeanDurationNS = mean(stat.durations)
973		stat.P50DurationNS = percentile(stat.durations, 50)
974		stat.P95DurationNS = percentile(stat.durations, 95)
975		stat.durations = nil
976	}
977	
978	func finalizeEdge(edge *ServiceEdge) {
979		sort.Slice(edge.durations, func(i, j int) bool { return edge.durations[i] < edge.durations[j] })
980		edge.MinDurationNS, edge.MaxDurationNS = bounds(edge.durations)
981		edge.MeanDurationNS = mean(edge.durations)
982		edge.P50DurationNS = percentile(edge.durations, 50)
983		edge.P95DurationNS = percentile(edge.durations, 95)
984		edge.durations = nil
985	}
986	
987	func finalizeStats(stats *GraphStats) {
988		sort.Slice(stats.durations, func(i, j int) bool { return stats.durations[i] < stats.durations[j] })
989		stats.DurationNS, _ = bounds(stats.durations)
990		stats.MeanDurationNS = mean(stats.durations)
991		stats.P50DurationNS = percentile(stats.durations, 50)
992		stats.P95DurationNS = percentile(stats.durations, 95)
993		stats.durations = nil
994	}
995	
996	func bounds(sorted []int64) (int64, int64) {
997		if len(sorted) == 0 {
998			return 0, 0
999		}
1000		return sorted[0], sorted[len(sorted)-1]
1001	}
1002	
1003	func mean(sorted []int64) int64 {
1004		if len(sorted) == 0 {
1005			return 0
1006		}
1007		total := int64(0)
1008		for _, value := range sorted {
1009			total += value
1010		}
1011		return total / int64(len(sorted))
1012	}
1013	
1014	// percentile uses the nearest-rank definition on already sorted input:
1015	// index = ceil(p/100 * n) - 1. Input is never mutated.
1016	func percentile(sorted []int64, p int) int64 {
1017		if len(sorted) == 0 {
1018			return 0
1019		}
1020		rank := (p*len(sorted) + 99) / 100
1021		if rank < 1 {
1022			rank = 1
1023		}
1024		if rank > len(sorted) {
1025			rank = len(sorted)
1026		}
1027		return sorted[rank-1]
1028	}
1029	
1030	func sortStrings(values []string) {
1031		sort.Strings(values)
1032	}
