111	// assignTiming derives self_time and the critical path of one subtree.
112	//
113	// LongestPath(t) is the largest sum of self_time on any path from t downwards.
114	// The critical branch K is the child with the largest LongestPath. self_time(t)
115	// is then everything of t's duration that K does not account for:
116	// duration(t) - LongestPath(K), where a leaf is its own critical branch. That
117	// makes self_time exactly the exclusive time off the critical path, so the self
118	// times along the critical path add up to duration(t), which is the invariant
119	// this service promises.
120	//
121	// Children are independent of each other, so LongestPath(child) can be computed
122	// before self_time(t) and does not change afterwards.
123	func assignTiming(node *TraceNode) {
124		if len(node.Children) == 0 {
125			node.SelfTimeNS = node.DurationNS
126			node.maxPath = node.DurationNS
127			return
128		}
129		critical := node.Children[0]
130		for _, child := range node.Children {
131			assignTiming(child)
132			if child.maxPath > critical.maxPath {
133				critical = child
134			}
135		}
136		selfTime := node.DurationNS - critical.maxPath
137		if selfTime < 0 {
138			selfTime = 0
139		}
140		node.SelfTimeNS = selfTime
141		node.maxPath = selfTime + critical.maxPath
142		if node.maxPath > node.DurationNS {
143			node.maxPath = node.DurationNS
144		}
145	}
