291	// parseTime accepts an RFC3339 timestamp with optional fractional seconds.
292	func parseTime(value string, field string) (time.Time, error) {
293		if strings.TrimSpace(value) == "" {
294			return time.Time{}, ValidationError("%s is required", field)
295		}
296		instant, err := time.Parse(time.RFC3339Nano, value)
297		if err != nil {
298			return time.Time{}, ValidationError("%s must be an RFC3339 timestamp", field)
299		}
300		return instant.UTC(), nil
301	}
