366	// validateSpanInput checks every rule that can be decided without looking at
367	// the other spans of the trace.
368	func validateSpanInput(input *SpanInput) (time.Time, error) {
369		if _, err := validateIdentifier(input.TraceID, "trace_id"); err != nil {
370			return time.Time{}, err
371		}
372		if _, err := validateIdentifier(input.SpanID, "span_id"); err != nil {
373			return time.Time{}, err
374		}
375		if input.ParentID != nil {
376			if strings.TrimSpace(*input.ParentID) == "" {
377				return time.Time{}, ValidationError("parent_id must be null or a non-empty identifier")
378			}
379		}
380		if _, err := validateText(input.Service, "service"); err != nil {
381			return time.Time{}, err
382		}
383		if _, err := validateText(input.Operation, "operation"); err != nil {
384			return time.Time{}, err
385		}
386		if !spanKinds[input.Kind] {
387			return time.Time{}, ValidationError("kind must be one of internal, server, client, producer or consumer")
388		}
389		if !spanStatuses[input.Status] {
390			return time.Time{}, ValidationError("status must be ok or error")
391		}
392		start, err := parseTime(input.StartTime, "start_time")
393		if err != nil {
394			return time.Time{}, err
395		}
396		if input.DurationNS < 0 {
397			return time.Time{}, ValidationError("duration_ns must be zero or positive")
398		}
399		if int64(start.UnixNano())+input.DurationNS > int64(maxTime.UnixNano()) {
400			return time.Time{}, ValidationError("start_time + duration_ns is beyond the supported range")
401		}
402		if len(input.Attributes) > maxAttributeCount {
403			return time.Time{}, ValidationError("attributes must contain at most %d entries", maxAttributeCount)
404		}
405		keys := make([]string, 0, len(input.Attributes))
406		for key := range input.Attributes {
407			keys = append(keys, key)
408		}
409		sort.Strings(keys)
410		for _, key := range keys {
411			if key == "" {
412				return time.Time{}, ValidationError("attribute keys must not be empty")
413			}
414			if len(key) > maxAttributeKey {
415				return time.Time{}, ValidationError("attribute key %s must be at most %d characters", key, maxAttributeKey)
416			}
417			if len(input.Attributes[key]) > maxAttributeValue {
418				return time.Time{}, ValidationError("attribute %s must be at most %d characters", key, maxAttributeValue)
419			}
420		}
421		if input.ParentID != nil && *input.ParentID == input.SpanID {
422			return time.Time{}, ValidationError("parent_id must not equal span_id on span %s", input.SpanID)
423		}
424		if input.ParentID == nil {
425			if input.SpanCount == nil {
426				return time.Time{}, ValidationError("span_count is required on a root span (parent_id null)")
427			}
428			if *input.SpanCount < 1 {
429				return time.Time{}, ValidationError("span_count must be at least 1")
430			}
431			if *input.SpanCount > maxSpanCount {
432				return time.Time{}, ValidationError("span_count must be at most %d", maxSpanCount)
433			}
434		} else if input.SpanCount != nil {
435			return time.Time{}, ValidationError("span_count is only allowed on a root span")
436		}
437		return start, nil
438	}
439	
440	// maxTime bounds start_time + duration_ns so that UnixNano arithmetic cannot
441	// overflow int64.
442	var maxTime = time.Date(2262, 4, 11, 23, 47, 16, 0, time.UTC)
443	
444	// lineOf resolves a span's trace id by walking parent links, which also detects
445	// a parent cycle and a parent that lives in another trace. A parent that has
446	// not been ingested yet simply ends the walk: every span of a trace carries the
447	// same trace id, so the input's own id is the answer.
448	func lineOf(spans map[string]*SpanInput, input *SpanInput) (string, error) {
449		seen := map[string]bool{input.SpanID: true}
450		current := input
451		for current.ParentID != nil {
452			parentID := *current.ParentID
453			if seen[parentID] {
454				return "", ConflictError("span %s has a cyclic parent_id chain", input.SpanID)
455			}
456			parent, found := spans[parentID]
457			if !found {
458				return input.TraceID, nil
459			}
460			seen[parentID] = true
461			if parent.TraceID != input.TraceID {
462				return "", ConflictError("span %s belongs to trace %s but its parent %s belongs to trace %s",
463					input.SpanID, input.TraceID, parentID, parent.TraceID)
464			}
465			current = parent
466		}
467		return input.TraceID, nil
468	}
469	
470	type treeBuilder struct {
471		spans      map[string]*SpanInput
472		children   map[string][]*SpanInput
473		roots      []*SpanInput
474		violations []Violation
475	}
476	
477	// assembleTrace rebuilds the span tree of one trace and derives every timing
478	// value. Violations are collected, never fatal, so a caller always sees why a
479	// trace is unusable.
480	func assembleTrace(traceID string, spans map[string]*SpanInput) *Trace {
481		trace := &Trace{
482			TraceID:    traceID,
483			SpanCount:  len(spans),
484			Valid:      true,
485			Violations: []Violation{},
486			Spans:      []*TraceNode{},
487		}
488		builder := &treeBuilder{
489			spans:    spans,
490			children: map[string][]*SpanInput{},
491		}
492		ids := make([]string, 0, len(spans))
493		for id := range spans {
494			ids = append(ids, id)
495		}
496		sort.Strings(ids)
497		for _, id := range ids {
498			span := spans[id]
499			if span.ParentID == nil {
500				builder.roots = append(builder.roots, span)
501				continue
502			}
503			if _, found := spans[*span.ParentID]; !found {
504				builder.violations = append(builder.violations, Violation{
505					Code:    "orphan_span",
506					TraceID: traceID,
507					SpanID:  span.SpanID,
508					Message: fmt.Sprintf("span %s references parent %s which is not part of trace %s",
509						span.SpanID, *span.ParentID, traceID),
510				})
511				continue
512			}
513			builder.children[*span.ParentID] = append(builder.children[*span.ParentID], span)
514		}
515		declared := 0
516		if len(builder.roots) == 1 && builder.roots[0].SpanCount != nil {
517			declared = *builder.roots[0].SpanCount
518		}
519		switch {
520		case len(builder.roots) == 1:
521		case len(builder.roots) == 0:
522			builder.violations = append(builder.violations, Violation{
523				Code:    "no_root_span",
524				TraceID: traceID,
525				SpanID:  "",
526				Message: fmt.Sprintf("trace %s has no span with a null parent_id", traceID),
527			})
528		default:
529			names := make([]string, 0, len(builder.roots))
530			for _, root := range builder.roots {
531				names = append(names, root.SpanID)
532			}
533			sort.Strings(names)
534			builder.violations = append(builder.violations, Violation{
535				Code:    "multiple_root_spans",
536				TraceID: traceID,
537				SpanID:  names[0],
538				Message: fmt.Sprintf("trace %s has %d root spans: %s", traceID, len(names), strings.Join(names, ", ")),
539			})
540		}
541		trace.RootSpanCount = declared
542		trace.Complete = len(builder.roots) == 1 && declared != 0 && declared == len(spans)
543		if declared != 0 && declared < len(spans) {
544			builder.violations = append(builder.violations, Violation{
545				Code:    "span_count_exceeded",
546				TraceID: traceID,
547				SpanID:  builder.roots[0].SpanID,
548				Message: fmt.Sprintf("trace %s declared span_count %d but %d spans were ingested",
549					traceID, declared, len(spans)),
550			})
551		}
552		if declared != 0 && declared > len(spans) {
553			builder.violations = append(builder.violations, Violation{
554				Code:    "trace_incomplete",
555				TraceID: traceID,
556				SpanID:  builder.roots[0].SpanID,
557				Message: fmt.Sprintf("trace %s declared span_count %d but only %d spans were ingested",
558					traceID, declared, len(spans)),
559			})
560		}
561	
562		// Every span that has no reachable root is still reported, as its own tree.
563		reachable := map[string]bool{}
564		for _, root := range builder.roots {
565			builder.markReachable(root, reachable)
566		}
567		for _, id := range ids {
568			if !reachable[id] && !builder.isOrphan(id) {
569				builder.violations = append(builder.violations, Violation{
570					Code:    "unreachable_span",
571					TraceID: traceID,
572					SpanID:  id,
573					Message: fmt.Sprintf("span %s is not reachable from a root span", id),
574				})
575			}
576		}
577	
578		sortedRoots := append([]*SpanInput{}, builder.roots...)
579		sort.Slice(sortedRoots, func(i, j int) bool {
580			left, _ := parseTime(sortedRoots[i].StartTime, "start_time")
581			right, _ := parseTime(sortedRoots[j].StartTime, "start_time")
582			if !left.Equal(right) {
583				return left.Before(right)
584			}
585			return sortedRoots[i].SpanID < sortedRoots[j].SpanID
586		})
587		for _, root := range sortedRoots {
588			start, _ := parseTime(root.StartTime, "start_time")
589			node := builder.buildNode(root, start, 0)
590			assignTiming(node)
591			trace.Spans = append(trace.Spans, flatten(node)...)
592			if trace.Root == nil {
593				trace.Root = node
594				trace.DurationNS = node.DurationNS
595			}
596		}
597		services := map[string]bool{}
598		for _, node := range trace.Spans {
599			collectServices(node, services)
600		}
601		trace.ServiceCount = len(services)
602		trace.ErrorSpans = countErrorSpans(trace.Spans)
603		trace.Valid = len(builder.violations) == 0
604		trace.Violations = builder.violations
605		sortViolations(trace.Violations)
606		return trace
607	}
608	
609	func (b *treeBuilder) isOrphan(id string) bool {
610		span := b.spans[id]
611		return span.ParentID != nil && b.spans[*span.ParentID] == nil
612	}
613	
614	func (b *treeBuilder) markReachable(span *SpanInput, seen map[string]bool) {
615		if seen[span.SpanID] {
616			return
617		}
618		seen[span.SpanID] = true
619		for _, child := range b.children[span.SpanID] {
620			b.markReachable(child, seen)
621		}
622	}
623	
624	// buildNode derives one node and everything below it. parentEnd is the
625	// exclusive end instant of the enclosing span; a child that overruns it is
626	// recorded as a violation and the node is still returned.
627	func (b *treeBuilder) buildNode(span *SpanInput, parentEnd time.Time, depth int) *TraceNode {
628		start, err := parseTime(span.StartTime, "start_time")
629		if err != nil {
630			start = time.Time{}
631		}
632		end := start.Add(time.Duration(span.DurationNS))
633		node := &TraceNode{
634			TraceID:      span.TraceID,
635			SpanID:       span.SpanID,
636			ParentID:     span.ParentID,
637			Service:      span.Service,
638			Operation:    span.Operation,
639			Kind:         span.Kind,
640			Status:       span.Status,
641			StartTime:    span.StartTime,
642			EndTime:      formatTime(end),
643			DurationNS:   span.DurationNS,
644			Depth:        depth,
645			Error:        span.Status == "error",
646			Attributes:   map[string]string{},
647			Children:     []*TraceNode{},
648			ErrorOrigins: []string{},
649		}
650		for key, value := range span.Attributes {
651			node.Attributes[key] = value
652		}
653		children := append([]*SpanInput{}, b.children[span.SpanID]...)
654		sort.Slice(children, func(i, j int) bool {
655			left, _ := parseTime(children[i].StartTime, "start_time")
656			right, _ := parseTime(children[j].StartTime, "start_time")
657			if !left.Equal(right) {
658				return left.Before(right)
659			}
660			return children[i].SpanID < children[j].SpanID
661		})
662		previousEnd := start
663		previousID := ""
664		for _, child := range children {
665			childStart, _ := parseTime(child.StartTime, "start_time")
666			childEnd := childStart.Add(time.Duration(child.DurationNS))
667			if childStart.Before(start) || childEnd.After(end) {
668				b.violations = append(b.violations, Violation{
669					Code:    "time_not_contained",
670					TraceID: span.TraceID,
671					SpanID:  child.SpanID,
672					Message: fmt.Sprintf("span %s runs from %s to %s which is not contained in parent %s from %s to %s",
673						child.SpanID, child.StartTime, formatTime(childEnd), span.SpanID, span.StartTime, formatTime(end)),
674				})
675			}
676			// Siblings must not overlap. Comparing each child against the furthest end
677			// seen so far catches an overlap with any earlier sibling, not only with
678			// the neighbour that starts just before it.
679			if previousID != "" && childStart.Before(previousEnd) {
680				b.violations = append(b.violations, Violation{
681					Code:    "sibling_overlap",
682					TraceID: span.TraceID,
683					SpanID:  previousID,
684					Message: fmt.Sprintf("span %s starts at %s before sibling %s ends at %s inside parent %s",
685						child.SpanID, child.StartTime, previousID, formatTime(previousEnd), span.SpanID),
686				})
687			}
688			if childEnd.After(previousEnd) {
689				previousEnd = childEnd
690				previousID = child.SpanID
691			}
692			node.Children = append(node.Children, b.buildNode(child, end, depth+1))
693		}
694		node.TotalDurationNS = span.DurationNS
695		for _, child := range node.Children {
696			if child.TotalDurationNS > span.DurationNS {
697				b.violations = append(b.violations, Violation{
698					Code:    "time_not_contained",
699					TraceID: span.TraceID,
700					SpanID:  child.SpanID,
701					Message: fmt.Sprintf("subtree of %s lasts %d but its parent %s only lasts %d",
702						child.SpanID, child.TotalDurationNS, span.SpanID, span.DurationNS),
703				})
704			}
705			if child.TotalDurationNS > node.TotalDurationNS {
706				node.TotalDurationNS = child.TotalDurationNS
707			}
708		}
709		origins := map[string]bool{}
710		if node.Error {
711			origins[span.SpanID] = true
712		}
713		for _, child := range node.Children {
714			for _, origin := range child.ErrorOrigins {
715				origins[origin] = true
716			}
717		}
718		for origin := range origins {
719			node.ErrorOrigins = append(node.ErrorOrigins, origin)
720		}
721		sort.Strings(node.ErrorOrigins)
722		node.ErrorOrigin = node.Error
723		// propagated marks a span whose subtree contains a failure that did not
724		// happen on the span itself. The declared status stays untouched: only the
725		// failing origin carries status "error".
726		node.Propagated = false
727		for _, origin := range node.ErrorOrigins {
728			if origin != node.SpanID {
729				node.Propagated = true
730				break
731			}
732		}
733		return node
734	}
735	
736	func collectServices(node *TraceNode, into map[string]bool) {
737		if into[node.Service] {
738			return
739		}
740		into[node.Service] = true
741		for _, child := range node.Children {
742			collectServices(child, into)
743		}
744	}
745	
746	// countErrorSpans counts failed spans in a flat span list. The list already
747	// contains every node once, so the nodes themselves are never walked again.
748	func countErrorSpans(nodes []*TraceNode) int {
749		total := 0
750		for _, node := range nodes {
751			if node.Error {
752				total++
753			}
754		}
755		return total
756	}
757	
758	func sortViolations(violations []Violation) {
759		sort.Slice(violations, func(i, j int) bool {
760			if violations[i].SpanID != violations[j].SpanID {
761				return violations[i].SpanID < violations[j].SpanID
762			}
763			return violations[i].Code < violations[j].Code
764		})
765	}
766	
767	// flatten walks the tree in pre-order and returns the nodes it contains.
768	func flatten(root *TraceNode) []*TraceNode {
769		if root == nil {
770			return nil
771		}
772		nodes := []*TraceNode{root}
773		for _, child := range root.Children {
774			nodes = append(nodes, flatten(child)...)
775		}
776		return nodes
777	}
778

