// traceIDsOf returns the trace ids of a GET /traces response in order.
func traceIDsOf(t *testing.T, listed map[string]any) []string {
	t.Helper()
	ids := []string{}
	for _, item := range listOf(t, listed["traces"]) {
		id, _ := objectOf(t, item)["trace_id"].(string)
		ids = append(ids, id)
	}
	return ids
